def article_searcher(genes=None, variants=None, diseases=None, chemicals=None, keywords=None, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "article_searcher"
    SOURCE_SYSTEM = "pubmed"
    RESPONSE_FORMAT = "markdown"
    TTL_SECONDS = 6 * 60 * 60  # 6h backend TTL for search caching (call-level)

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        # Deterministic-enough unique id with time ordering; keep vendor-like prefix.
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ms:013d}{rnd:020x}"[:26]

    def _ensure_list(v):
        # Accept None -> [], list -> list, non-list -> VALIDATION_ERROR.
        if v is None:
            return []
        if not isinstance(v, list):
            return None
        return v

    def _coerce_terms(lst):
        # Article_searcher must store request_json verbatim (including non-strings if caller passed them),
        # but canonicalization should normalize to strings; accept numbers by stringifying.
        out = []
        for it in lst:
            if it is None:
                continue
            if isinstance(it, (str, int, float, bool)):
                out.append(str(it))
            else:
                # unsupported item types: stringify via JSON if possible, else repr
                try:
                    out.append(json.dumps(it, ensure_ascii=False, sort_keys=True))
                except Exception:
                    out.append(repr(it))
        return out

    def _canon_terms(lst):
        seen = set()
        normed = []
        for raw in _coerce_terms(lst):
            t = re.sub(r"\s+", " ", raw.strip()).lower()
            if not t:
                continue
            if t in seen:
                continue
            seen.add(t)
            normed.append(t)
        return normed

    def _canonicalize(req):
        return {
            "genes": _canon_terms(req.get("genes", [])),
            "variants": _canon_terms(req.get("variants", [])),
            "diseases": _canon_terms(req.get("diseases", [])),
            "chemicals": _canon_terms(req.get("chemicals", [])),
            "keywords": _canon_terms(req.get("keywords", [])),
        }

    def _hash_canon(canon):
        b = json.dumps(canon, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _resolve_client_ambient():
        # No explicit credential parameter for this tool: pick an active client that can serve the call.
        clients = _load("api_clients.json")
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        # If none active, pick any existing row to log the call against; still must reject as not active.
        for c in clients:
            if isinstance(c, dict):
                return c
        return None

    def _count_usage(tool_calls, client_id, now_dt):
        win60 = now_dt - datetime.timedelta(seconds=60)
        win24 = now_dt - datetime.timedelta(hours=24)
        c60 = 0
        c24 = 0
        for r in tool_calls:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            st = r.get("status")
            if st not in ("succeeded", "failed", "cancelled"):
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if created >= win60:
                c60 += 1
            if created >= win24:
                c24 += 1
        return c60, c24

    def _append_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _patch_call(tool_calls, call_id, **patch):
        now_iso = _now_iso()
        for r in tool_calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                r.update(patch)
                r["updated_at"] = now_iso
                if r.get("status") in ("succeeded", "failed", "rate_limited", "cancelled"):
                    r["completed_at"] = r.get("completed_at") or now_iso
                _save("tool_calls.json", tool_calls)
                return r
        return None

    # Validate inputs (relaxed: accept non-string items; arrays required when provided)
    genes_l = _ensure_list(genes)
    variants_l = _ensure_list(variants)
    diseases_l = _ensure_list(diseases)
    chemicals_l = _ensure_list(chemicals)
    keywords_l = _ensure_list(keywords)
    if genes_l is None or variants_l is None or diseases_l is None or chemicals_l is None or keywords_l is None:
        return _err("VALIDATION_ERROR", "genes/variants/diseases/chemicals/keywords must be arrays when provided (or omitted).")

    req_json = {
        "genes": genes_l,
        "variants": variants_l,
        "diseases": diseases_l,
        "chemicals": chemicals_l,
        "keywords": keywords_l,
    }
    canon = _canonicalize(req_json)
    req_hash = _hash_canon(canon)

    # Prepare logging row (must be created with received before execution)
    tool_calls = _load("tool_calls.json")
    clients = _load("api_clients.json")
    client = _resolve_client_ambient()
    if client is None:
        # no client context exists at all; still record? cannot due to FK; return UNAUTHORIZED
        return _err("UNAUTHORIZED", "No api_client context available to serve this request.")

    client_id = client.get("id")
    now_dt = _now_dt()
    now_iso = _now_iso()
    call_id = "biomcp_call_" + _ulid_like("")  # stable prefix like existing data

    call_row = {
        "id": call_id,
        "client_id": client_id,
        "tool_name": TOOL,
        "status": "received",
        "request_json": req_json,
        "request_canonical_json": canon,
        "request_hash": req_hash,
        "source_system": SOURCE_SYSTEM,
        "cache_mode": "miss",
        "cache_ttl_seconds": TTL_SECONDS,
        "response_format": RESPONSE_FORMAT,
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    _append_call(tool_calls, call_row)

    # Enforce client active
    if client.get("status") in ("suspended", "deleted"):
        _patch_call(tool_calls, call_id, status="rate_limited", error_code="CLIENT_NOT_ACTIVE", error_message="Caller api_client is not active.")
        return _err("RATE_LIMIT", "Client is not active.", tool_call_id=call_id, error_code="CLIENT_NOT_ACTIVE")

    # Enforce rate limits (rolling)
    quota_min = client.get("quota_requests_per_minute")
    quota_day = client.get("quota_requests_per_day")
    if not isinstance(quota_min, int):
        quota_min = 60
    if not isinstance(quota_day, int):
        quota_day = 5000
    c60, c24 = _count_usage(tool_calls, client_id, now_dt)
    if c60 >= quota_min or c24 >= quota_day:
        _patch_call(
            tool_calls, call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 60s for this client." if c60 >= quota_min else "Too many requests in the last 24h for this client."
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", tool_call_id=call_id, error_code="RATE_LIMIT_EXCEEDED")

    # Transition to running
    _patch_call(tool_calls, call_id, status="running")

    # Cache lookup: same client/tool/hash succeeded recently within TTL => hit
    cached = None
    for r in reversed(tool_calls):
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if r.get("tool_name") != TOOL:
            continue
        if r.get("request_hash") != req_hash:
            continue
        if r.get("status") != "succeeded":
            continue
        created = _parse_dt(r.get("created_at"))
        if not created:
            continue
        if (now_dt - created).total_seconds() <= TTL_SECONDS and isinstance(r.get("response_markdown"), str):
            cached = r
            break

    if cached is not None:
        md = cached.get("response_markdown")
        _patch_call(tool_calls, call_id, status="succeeded", cache_mode="hit", response_markdown=md, response_json=cached.get("response_json"))
        # update last_seen_at
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                c["last_seen_at"] = _now_iso()
                c["updated_at"] = _now_iso()
                _save("api_clients.json", clients)
                break
        return {"data": {"tool_call_id": call_id, "cache_mode": "hit", "markdown": md}}

    # Synthesize results from local pubmed_articles cache (offline)
    articles = _load("pubmed_articles.json")
    terms = canon["genes"] + canon["variants"] + canon["diseases"] + canon["chemicals"] + canon["keywords"]
    terms = [t for t in terms if t]
    def _score(a):
        blob = " ".join([
            str(a.get("title") or ""),
            str(a.get("abstract") or ""),
            str(a.get("journal") or ""),
            " ".join(a.get("authors") or []) if isinstance(a.get("authors"), list) else "",
            " ".join(a.get("mesh_terms") or []) if isinstance(a.get("mesh_terms"), list) else "",
            " ".join(a.get("keywords") or []) if isinstance(a.get("keywords"), list) else "",
            str(a.get("doi") or ""),
        ]).lower()
        s = 0
        for t in terms:
            if t and t in blob:
                s += 1
        return s

    candidates = []
    for a in articles:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "tombstoned":
            continue
        sc = _score(a) if terms else 0
        if terms and sc == 0:
            continue
        candidates.append((sc, a))

    candidates.sort(key=lambda x: (-x[0], str(x[1].get("pmid") or "")))
    top = [a for _, a in candidates[:25]]
    if not top and articles:
        # fallback: show newest-ish by fetched_at if no term hits
        def _fetched_key(a):
            dt = _parse_dt(a.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        non_tomb = [a for a in articles if isinstance(a, dict) and a.get("status") != "tombstoned"]
        non_tomb.sort(key=_fetched_key, reverse=True)
        top = non_tomb[:25]

    lines = [f"Top PubMed results ({len(top)}):"]
    for a in top:
        pmid = a.get("pmid") or ""
        title = a.get("title") or "(no title)"
        # infer simple type label
        t_lower = title.lower()
        label = "Article"
        if "review" in t_lower:
            label = "Review"
        elif "trial" in t_lower or "randomized" in t_lower:
            label = "Clinical trial"
        lines.append(f"- PMID {pmid} — {title} — {label}")
    md = "\n".join(lines)

    _patch_call(tool_calls, call_id, status="succeeded", cache_mode="miss", response_markdown=md, response_json={"pmids": [a.get("pmid") for a in top if isinstance(a, dict)]})

    # update last_seen_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            _save("api_clients.json", clients)
            break

    return {"data": {"tool_call_id": call_id, "cache_mode": "miss", "markdown": md}}

def trial_locations(nct_id, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "trial_locations"
    SOURCE_SYSTEM = "clinicaltrials"
    RESPONSE_FORMAT = "markdown"
    TTL_SECONDS = 24 * 60 * 60  # 24h

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ms:013d}{rnd:020x}"[:26]

    def _hash_canon(canon):
        b = json.dumps(canon, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _resolve_client_ambient():
        clients = _load("api_clients.json")
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        for c in clients:
            if isinstance(c, dict):
                return c
        return None

    def _count_usage(tool_calls, client_id, now_dt):
        win60 = now_dt - datetime.timedelta(seconds=60)
        win24 = now_dt - datetime.timedelta(hours=24)
        c60 = 0
        c24 = 0
        for r in tool_calls:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            st = r.get("status")
            if st not in ("succeeded", "failed", "cancelled"):
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if created >= win60:
                c60 += 1
            if created >= win24:
                c24 += 1
        return c60, c24

    def _append_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _patch_call(tool_calls, call_id, **patch):
        now_iso = _now_iso()
        for r in tool_calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                r.update(patch)
                r["updated_at"] = now_iso
                if r.get("status") in ("succeeded", "failed", "rate_limited", "cancelled"):
                    r["completed_at"] = r.get("completed_at") or now_iso
                _save("tool_calls.json", tool_calls)
                return r
        return None

    # Validate input
    if not isinstance(nct_id, str) or not nct_id.strip():
        return _err("VALIDATION_ERROR", "nct_id must be a non-empty string")
    nct_id = nct_id.strip()
    if not re.match(r"^NCT[0-9]{8}$", nct_id):
        # Must fail with error_code INVALID_NCT_ID, and must be recorded as a tool_call lifecycle.
        client = _resolve_client_ambient()
        if client is None:
            return _err("UNAUTHORIZED", "No api_client context available to serve this request.")
        tool_calls = _load("tool_calls.json")
        call_id = "biomcp_call_" + _ulid_like("")
        now_iso = _now_iso()
        canon = {"nct_id": nct_id}
        row = {
            "id": call_id,
            "client_id": client.get("id"),
            "tool_name": TOOL,
            "status": "received",
            "request_json": {"nct_id": nct_id},
            "request_canonical_json": canon,
            "request_hash": _hash_canon(canon),
            "source_system": SOURCE_SYSTEM,
            "cache_mode": "bypass",
            "cache_ttl_seconds": TTL_SECONDS,
            "response_format": RESPONSE_FORMAT,
            "response_markdown": None,
            "response_json": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "upstream_latency_ms": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "completed_at": None,
        }
        _append_call(tool_calls, row)
        _patch_call(tool_calls, call_id, status="running")
        _patch_call(tool_calls, call_id, status="failed", error_code="INVALID_NCT_ID", error_message="nct_id must match ^NCT[0-9]{8}$")
        return _err("VALIDATION_ERROR", "nct_id must match ^NCT[0-9]{8}$", tool_call_id=call_id, error_code="INVALID_NCT_ID")

    # Start tool_call logging
    client = _resolve_client_ambient()
    if client is None:
        return _err("UNAUTHORIZED", "No api_client context available to serve this request.")
    client_id = client.get("id")

    tool_calls = _load("tool_calls.json")
    clients = _load("api_clients.json")
    now_dt = _now_dt()
    now_iso = _now_iso()
    canon = {"nct_id": nct_id}
    req_hash = _hash_canon(canon)
    call_id = "biomcp_call_" + _ulid_like("")
    row = {
        "id": call_id,
        "client_id": client_id,
        "tool_name": TOOL,
        "status": "received",
        "request_json": {"nct_id": nct_id},
        "request_canonical_json": canon,
        "request_hash": req_hash,
        "source_system": SOURCE_SYSTEM,
        "cache_mode": "miss",
        "cache_ttl_seconds": TTL_SECONDS,
        "response_format": RESPONSE_FORMAT,
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    _append_call(tool_calls, row)

    # Enforce client active
    if client.get("status") in ("suspended", "deleted"):
        _patch_call(tool_calls, call_id, status="rate_limited", error_code="CLIENT_NOT_ACTIVE", error_message="Caller api_client is not active.")
        return _err("RATE_LIMIT", "Client is not active.", tool_call_id=call_id, error_code="CLIENT_NOT_ACTIVE")

    # Enforce rate limits
    quota_min = client.get("quota_requests_per_minute")
    quota_day = client.get("quota_requests_per_day")
    if not isinstance(quota_min, int):
        quota_min = 60
    if not isinstance(quota_day, int):
        quota_day = 5000
    c60, c24 = _count_usage(tool_calls, client_id, now_dt)
    if c60 >= quota_min or c24 >= quota_day:
        _patch_call(
            tool_calls, call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 60s for this client." if c60 >= quota_min else "Too many requests in the last 24h for this client."
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", tool_call_id=call_id, error_code="RATE_LIMIT_EXCEEDED")

    _patch_call(tool_calls, call_id, status="running")

    # Retrieve from local cache (offline) and upsert required module field
    trials = _load("clinical_trials.json")
    trial = None
    for t in trials:
        if isinstance(t, dict) and t.get("nct_id") == nct_id:
            trial = t
            break

    # mark stale based on TTL and fetched_at
    stale = False
    if trial and trial.get("status") != "tombstoned":
        fetched = _parse_dt(trial.get("fetched_at"))
        if fetched and (now_dt - fetched).total_seconds() > TTL_SECONDS:
            stale = True
            # transition active->stale or keep stale
            if trial.get("status") == "active":
                trial["status"] = "stale"
                trial["updated_at"] = _now_iso()
                _save("clinical_trials.json", trials)

    # If missing or stale, "refresh" by ensuring ContactsLocationsModule exists (best-effort offline)
    if trial is None:
        trial = {
            "id": f"nct:{nct_id}",
            "nct_id": nct_id,
            "status": "active",
            "overall_status": None,
            "brief_title": None,
            "official_title": None,
            "sponsor": None,
            "phases": None,
            "conditions": None,
            "interventions": None,
            "brief_summary": None,
            "protocol_module_json": None,
            "contacts_locations_module_json": None,
            "outcomes_module_json": None,
            "results_section_json": None,
            "references_module_json": None,
            "source_url": f"https://clinicaltrials.gov/study/{nct_id}",
            "fetched_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        trials.append(trial)
        _save("clinical_trials.json", trials)

    # Ensure contacts_locations_module_json exists with a dict shape (fixes prior AttributeError)
    clm = trial.get("contacts_locations_module_json")
    if not isinstance(clm, dict):
        clm = {}
    facilities = clm.get("locations")
    if not isinstance(facilities, list):
        # try common CT.gov-like nesting, else empty
        facilities = []
        # do not throw on strings/etc.
        for key in ("locations", "LocationList", "facilities"):
            v = clm.get(key) if isinstance(clm, dict) else None
            if isinstance(v, list):
                facilities = v
                break
    # Normalize facilities to list of dicts
    norm_fac = []
    for f in facilities:
        if isinstance(f, dict):
            norm_fac.append(f)
    clm["locations"] = norm_fac
    trial["contacts_locations_module_json"] = clm
    # refresh fetched_at and status if stale
    trial["fetched_at"] = _now_iso()
    if trial.get("status") == "stale":
        trial["status"] = "active"
    trial["updated_at"] = _now_iso()
    _save("clinical_trials.json", trials)

    # Render markdown
    lines = [f"Locations for **{nct_id}**:"]
    if not norm_fac:
        lines.append("- No locations available in cache.")
    else:
        for loc in norm_fac[:50]:
            name = loc.get("facility") or loc.get("name") or "Facility"
            city = loc.get("city") or ""
            state = loc.get("state") or loc.get("stateProvince") or ""
            country = loc.get("country") or ""
            addr = ", ".join([p for p in [city, state, country] if p])
            contact = loc.get("contact") if isinstance(loc.get("contact"), dict) else {}
            phone = contact.get("phone") or loc.get("phone") or ""
            email = contact.get("email") or loc.get("email") or ""
            line = f"- {name}"
            if addr:
                line += f" — {addr}"
            if phone or email:
                extras = " / ".join([p for p in [phone, email] if p])
                line += f" — {extras}"
            lines.append(line)
    md = "\n".join(lines)

    _patch_call(tool_calls, call_id, status="succeeded", cache_mode="miss" if stale else "hit" if not stale and trial else "miss", response_markdown=md, response_json={"nct_id": nct_id, "locations_count": len(norm_fac)})

    # update last_seen_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            _save("api_clients.json", clients)
            break

    return {"data": {"tool_call_id": call_id, "markdown": md}}

