    def _log_call_finish(tool_calls, call_row, status, http_status=None, error_code=None, error_message=None,
                         cache_mode=None, cache_ttl_seconds=None, response_format=None,
                         response_markdown=None, response_json=None, upstream_latency_ms=None):
        now = _now_iso()
        call_row["status"] = status
        call_row["updated_at"] = now
        call_row["completed_at"] = now
