        nct_id_val = None
    else:
        nct_id_val = nct_id.strip()

    # Resolve ambient client context: pick any active client that can serve the call.
    api_clients = _load("api_clients.json")
    client = None
    for c in api_clients:
        if c.get("status") == "active":
            client = c
            break
    if client is None:
        # No active client exists -> unauthorized
        return _err("UNAUTHORIZED", "No active API client available to serve request.")

    tool_calls = _load("tool_calls.json")

    request_json = {"nct_id": nct_id}
    canon = _canonicalize(request_json)
    req_hash = _hash_req(canon)

    call_row = {
        "id": _ulid_like(),
        "client_id": client.get("id"),
        "tool_name": "trial_outcomes",
        "status": "received",
        "request_json": request_json,
        "request_canonical_json": canon,
        "request_hash": req_hash,
        "source_system": "clinicaltrials",
        "cache_mode": "miss",
        "cache_ttl_seconds": None,
        "response_format": "markdown",
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
