    def _within_window(row, seconds):
        dt = _parse_iso(row.get("created_at"))
        if dt is None:
            return False
        return (datetime.datetime.utcnow() - dt).total_seconds() <= seconds

    minute_cap = client.get("quota_requests_per_minute")
    day_cap = client.get("quota_requests_per_day")
    if not isinstance(minute_cap, int) or not isinstance(day_cap, int):
        # misconfigured client; fail but record
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "failed", error_code="CLIENT_QUOTA_MISCONFIG",
                         error_message="Client quota configuration invalid.", cache_mode="bypass",
                         response_format="markdown", response_markdown=None)
        return _finalize_and_return(_err("CONFLICT", "Client quota misconfigured.", error_code="CLIENT_QUOTA_MISCONFIG"))

    minute_count = 0
    day_count = 0
    for r in tool_calls:
        if r.get("client_id") != client.get("id"):
            continue
        st = r.get("status")
        if st not in ("succeeded", "failed", "cancelled"):
            continue
        if _within_window(r, 60):
            minute_count += 1
        if _within_window(r, 24 * 3600):
            day_count += 1

    if minute_count >= minute_cap or day_count >= day_cap:
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "rate_limited", error_code="RATE_LIMIT_EXCEEDED",
                         error_message="Client rate limit exceeded.", cache_mode="bypass",
                         response_format="markdown", response_markdown=None)
        return _finalize_and_return(_err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT_EXCEEDED"))

    # Transition to running
    call_row["status"] = "running"
    call_row["updated_at"] = _now_iso()

    # Validate NCT ID pattern
    if not isinstance(nct_id, str) or re.match(r"^NCT[0-9]{8}$", nct_id_val or "") is None:
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_NCT_ID",
                         error_message="nct_id must match ^NCT[0-9]{8}$",
                         cache_mode="bypass", response_format="markdown")
        return _finalize_and_return(_err("VALIDATION_ERROR", "Invalid NCT ID.", error_code="INVALID_NCT_ID"))

    # Cache TTL policy for trial_* tools (seconds)
    TTL = 7 * 24 * 3600
    call_row["cache_ttl_seconds"] = TTL

    clinical_trials = _load("clinical_trials.json")

    trial_id = f"nct:{nct_id_val}"
    trial = None
    for tr in clinical_trials:
        if tr.get("nct_id") == nct_id_val or tr.get("id") == trial_id:
            trial = tr
            break

    # Determine stale based on fetched_at and TTL, unless tombstoned
    stale = True
    if trial and trial.get("status") != "tombstoned":
        fetched_dt = _parse_iso(trial.get("fetched_at"))
        if fetched_dt is not None:
            age = (datetime.datetime.utcnow() - fetched_dt).total_seconds()
            stale = age > TTL
        else:
            stale = True
        if stale and trial.get("status") == "active":
            trial["status"] = "stale"
            trial["updated_at"] = _now_iso()

    # We cannot actually call upstream offline; treat "upstream" as unavailable.
    upstream_available = False

    # If we have cached module data, serve it (hit) even if stale; also mark stale if beyond TTL.
    outcomes_mod = trial.get("outcomes_module_json") if trial else None
    results_sec = trial.get("results_section_json") if trial else None

    if (outcomes_mod or results_sec) and trial and trial.get("status") != "tombstoned":
        call_row["cache_mode"] = "hit" if not stale else "hit"
        # If stale, keep stale marker; "refreshed on next access" cannot be done offline.
        md_lines = []
        md_lines.append(f"# Trial outcomes: {nct_id_val}")
        title = trial.get("brief_title") or trial.get("official_title") or "Title unavailable"
        overall_status = trial.get("overall_status") or "Status unavailable"
        md_lines.append(f"**Title:** {title}")
        md_lines.append(f"**Overall status:** {overall_status}")
        if trial.get("source_url"):
            md_lines.append(f"**Source:** {trial.get('source_url')}")
        if trial.get("status") == "stale":
            md_lines.append("")
            md_lines.append("_Note: cached trial record is marked **stale** (TTL exceeded); may be out of date._")

        def _render_outcomes(m):
            out = []
            if not isinstance(m, dict):
                return out
            out.append("## Outcomes (cached)")
            prim = m.get("primaryOutcomes") or m.get("PrimaryOutcomeList") or m.get("primary_outcomes")
            sec = m.get("secondaryOutcomes") or m.get("SecondaryOutcomeList") or m.get("secondary_outcomes")
            other = m.get("otherOutcomes") or m.get("OtherOutcomeList") or m.get("other_outcomes")

            def fmt_list(lst, heading):
                if not lst:
                    return
                out.append(f"### {heading}")
                if isinstance(lst, dict) and "outcome" in lst and isinstance(lst["outcome"], list):
                    items = lst["outcome"]
                else:
                    items = lst if isinstance(lst, list) else [lst]
                for i, it in enumerate(items, 1):
                    if isinstance(it, dict):
                        measure = it.get("measure") or it.get("OutcomeMeasure") or it.get("title") or it.get("name")
                        timef = it.get("timeFrame") or it.get("OutcomeTimeFrame") or it.get("time_frame")
                        desc = it.get("description") or it.get("OutcomeDescription") or it.get("descriptionText")
                        out.append(f"{i}. **{measure or 'Outcome'}**")
                        if timef:
                            out.append(f"   - Time frame: {timef}")
                        if desc:
                            out.append(f"   - Description: {desc}")
                    else:
                        out.append(f"{i}. {str(it)}")

            fmt_list(prim, "Primary outcomes")
            fmt_list(sec, "Secondary outcomes")
            fmt_list(other, "Other outcomes")
            return out

        def _render_results(m):
            out = []
            if not isinstance(m, dict):
                return out
            out.append("## Results (cached)")
            # very lightweight extraction
            flow = m.get("participantFlowModule") or m.get("ParticipantFlowModule")
            baseline = m.get("baselineCharacteristicsModule") or m.get("BaselineCharacteristicsModule")
            adverse = m.get("adverseEventsModule") or m.get("AdverseEventsModule")
            outcomes = m.get("outcomeMeasuresModule") or m.get("OutcomeMeasuresModule")
            if flow:
                out.append("### Participant flow")
                out.append("_Participant flow data present in cache._")
            if baseline:
                out.append("### Baseline characteristics")
                out.append("_Baseline characteristics present in cache._")
            if outcomes:
                out.append("### Outcome measures / analyses")
                out.append("_Outcome measure results present in cache._")
            if adverse:
                out.append("### Adverse events")
                out.append("_Adverse events data present in cache._")
            if len(out) == 1:
                out.append("_No results sections found in cached record._")
            return out

        md_lines += [""] + _render_outcomes(outcomes_mod)
        md_lines += [""] + _render_results(results_sec)
        markdown = "\n".join([l for l in md_lines if l is not None])

        # Upsert touch timestamps (serving cached still updates updated_at; fetched_at unchanged)
        if trial:
            trial["updated_at"] = _now_iso()
            if trial.get("id") is None:
                trial["id"] = trial_id
            if trial.get("nct_id") is None:
                trial["nct_id"] = nct_id_val
            # persist trial update
            for i, tr in enumerate(clinical_trials):
                if tr.get("id") == trial.get("id") or tr.get("nct_id") == nct_id_val:
                    clinical_trials[i] = trial
                    break
            _save("clinical_trials.json", clinical_trials)

        client["last_seen_at"] = _now_iso()
        client["updated_at"] = _now_iso()
        for i, c in enumerate(api_clients):
            if c.get("id") == client.get("id"):
                api_clients[i] = client
                break
        _save("api_clients.json", api_clients)

        _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, error_code=None,
                         error_message=None, cache_mode=call_row.get("cache_mode"),
                         cache_ttl_seconds=TTL, response_format="markdown",
                         response_markdown=markdown, response_json=None,
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize_and_return(markdown)

    # No cached module exists; offline "upstream" fails => NOT_FOUND/failed with error_code
    # But we must still upsert clinical_trials only on success; here it's failure.
    call_row["cache_mode"] = "miss"
    _log_call_finish(tool_calls, call_row, "failed", http_status=None, error_code="UPSTREAM_UNAVAILABLE",
                     error_message="Upstream ClinicalTrials.gov not available in offline datastore.",
                     cache_mode="miss", cache_ttl_seconds=TTL, response_format="markdown",
                     response_markdown=None, response_json=None, upstream_latency_ms=int((time.time() - t0) * 1000))
    return _finalize_and_return(_err("NOT_FOUND", "Trial outcomes not available in cache.", error_code="UPSTREAM_UNAVAILABLE"))

