        refs = None
        if isinstance(refs_mod, dict):
            refs = refs_mod.get("references") or refs_mod.get("ReferenceList") or refs_mod.get("reference")
            if refs is None and "module" in refs_mod and isinstance(refs_mod["module"], dict):
                refs = refs_mod["module"].get("references")
        if refs is None:
            md.append("_No references found in cached record._")
        else:
            if isinstance(refs, dict) and "reference" in refs and isinstance(refs["reference"], list):
                items = refs["reference"]
            elif isinstance(refs, list):
                items = refs
            else:
                items = [refs]
            if not items:
                md.append("_No references found in cached record._")
            else:
                for i, it in enumerate(items, 1):
                    if isinstance(it, dict):
                        citation = it.get("citation") or it.get("Citation") or it.get("referenceCitation") or it.get("title")
                        pmid = it.get("pmid") or it.get("PMID") or it.get("pubMedId")
                        rtype = it.get("type") or it.get("ReferenceType") or it.get("referenceType")
                        parts = []
                        if citation:
                            parts.append(citation)
                        if pmid:
                            parts.append(f"PMID: {pmid}")
                        if rtype:
                            parts.append(f"Type: {rtype}")
                        md.append(f"{i}. " + (" — ".join(parts) if parts else "Reference"))
                    else:
                        md.append(f"{i}. {str(it)}")

        markdown = "\n".join(md)

        # Persist trial touch
        trial["updated_at"] = _now_iso()
        if not trial.get("id"):
            trial["id"] = trial_id
        if not trial.get("nct_id"):
            trial["nct_id"] = nct_id_val
        for i, tr in enumerate(clinical_trials):
            if tr.get("id") == trial.get("id") or tr.get("nct_id") == nct_id_val:
                clinical_trials[i] = trial
                break
        _save("clinical_trials.json", clinical_trials)

        client["last_seen_at"] = _now_iso()
        client["updated_at"] = _now_iso()
        for i, c in enumerate(api_clients):
            if c.get("id") == client.get("id"):
                api_clients[i] = client
                break
        _save("api_clients.json", api_clients)

        _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, cache_mode="hit",
                         cache_ttl_seconds=TTL, response_format="markdown",
                         response_markdown=markdown, response_json=None,
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize_and_return(markdown)

    call_row["cache_mode"] = "miss"
    _log_call_finish(tool_calls, call_row, "failed", error_code="UPSTREAM_UNAVAILABLE",
                     error_message="Upstream ClinicalTrials.gov not available in offline datastore.",
                     cache_mode="miss", cache_ttl_seconds=TTL, response_format="markdown",
                     response_markdown=None, response_json=None,
                     upstream_latency_ms=int((time.time() - t0) * 1000))
    return _finalize_and_return(_err("NOT_FOUND", "Trial references not available in cache.", error_code="UPSTREAM_UNAVAILABLE"))

def trial_searcher(conditions=None, interventions=None, terms=None, recruiting_status=None, phase=None, location=None, start_date_from=None, start_date_to=None, completion_date_from=None, completion_date_to=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, (int, float)):
            return datetime.datetime.utcfromtimestamp(dt)
        if not isinstance(dt, str):
            return None
        s = dt.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s2 = s[:-1]
        else:
            s2 = s
        try:
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _ulid_like():
        t_ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"ulid_{t_ms:x}_{rnd:x}"

    def _canonicalize_trial_query(q):
        # Normalize case/whitespace, de-dupe arrays, stable ordering
        def norm_str(s):
            return " ".join(s.strip().lower().split())

        def norm_list(lst):
            if lst is None:
                return []
            if not isinstance(lst, list):
                return None
            out = []
            seen = set()
            for x in lst:
                if not isinstance(x, str):
                    return None
                nx = norm_str(x)
                if not nx:
                    continue
                if nx in seen:
                    continue
                seen.add(nx)
                out.append(nx)
            out.sort()
            return out

        cq = {}
        for k in ("conditions", "interventions", "terms", "recruiting_status", "phase"):
            nl = norm_list(q.get(k))
            if nl is None:
                return None
            cq[k] = nl

        loc = q.get("location")
        if loc is None:
            cq["location"] = None
        else:
            if not isinstance(loc, dict):
                return None
            allowed = {"lat", "lon", "distance_miles"}
            for kk in loc.keys():
                if kk not in allowed:
                    return None
            loc2 = {}
            for kk in ("lat", "lon", "distance_miles"):
                if kk in loc and loc[kk] is not None:
                    if not isinstance(loc[kk], (int, float)):
                        return None
                    loc2[kk] = float(loc[kk])
            cq["location"] = loc2 if loc2 else {}

        for dk in ("start_date_from", "start_date_to", "completion_date_from", "completion_date_to"):
            v = q.get(dk)
            if v is None:
                cq[dk] = None
            else:
                if not isinstance(v, str) or not v.strip():
                    return None
                # Keep as trimmed string; validity best-effort
                cq[dk] = v.strip()

        # canonical keys order
        return {k: cq[k] for k in sorted(cq.keys())}

    def _hash_req(canon_obj):
        s = json.dumps(canon_obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log_call_finish(tool_calls, call_row, status, http_status=None, error_code=None, error_message=None,
                         cache_mode=None, cache_ttl_seconds=None, response_format=None,
                         response_markdown=None, response_json=None, upstream_latency_ms=None):
        now = _now_iso()
        call_row["status"] = status
        call_row["updated_at"] = now
        call_row["completed_at"] = now
        call_row["http_status"] = http_status
        call_row["error_code"] = error_code
        call_row["error_message"] = error_message
        if cache_mode is not None:
            call_row["cache_mode"] = cache_mode
        if cache_ttl_seconds is not None:
            call_row["cache_ttl_seconds"] = cache_ttl_seconds
        if response_format is not None:
            call_row["response_format"] = response_format
        call_row["response_markdown"] = response_markdown
        call_row["response_json"] = response_json
        call_row["upstream_latency_ms"] = upstream_latency_ms
        return call_row

    t0 = time.time()
    now_iso = _now_iso()

    # Resolve client (ambient)
    api_clients = _load("api_clients.json")
    client = None
    for c in api_clients:
        if c.get("status") == "active":
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active API client available to serve request.")

    tool_calls = _load("tool_calls.json")

    # Build request_json verbatim: must support lists even if empty.
    def _list_or_empty(x, name):
        if x is None:
            return []
        if not isinstance(x, list):
            return None
        for v in x:
            if not isinstance(v, str):
                return None
        return x

    req = {
        "conditions": _list_or_empty(conditions, "conditions"),
        "interventions": _list_or_empty(interventions, "interventions"),
        "terms": _list_or_empty(terms, "terms"),
        "recruiting_status": _list_or_empty(recruiting_status, "recruiting_status"),
        "phase": _list_or_empty(phase, "phase"),
        "location": location,
        "start_date_from": start_date_from,
        "start_date_to": start_date_to,
        "completion_date_from": completion_date_from,
        "completion_date_to": completion_date_to,
    }

    # Validate list-typed fields
    for k in ("conditions", "interventions", "terms", "recruiting_status", "phase"):
        if req[k] is None:
            # log received then fail
            canon_bad = {}
            canon_bad[k] = "INVALID"
            canon = canon_bad
            req_hash = _hash_req(canon)
            call_row = {
                "id": _ulid_like(),
                "client_id": client.get("id"),
                "tool_name": "trial_searcher",
                "status": "received",
                "request_json": {
                    "conditions": conditions if conditions is not None else [],
                    "interventions": interventions if interventions is not None else [],
                    "terms": terms if terms is not None else [],
                    "recruiting_status": recruiting_status if recruiting_status is not None else [],
                    "phase": phase if phase is not None else [],
                    "location": location,
                    "start_date_from": start_date_from,
                    "start_date_to": start_date_to,
                    "completion_date_from": completion_date_from,
                    "completion_date_to": completion_date_to,
                },
                "request_canonical_json": canon,
                "request_hash": req_hash,
                "source_system": "clinicaltrials",
                "cache_mode": "bypass",
                "cache_ttl_seconds": 7 * 24 * 3600,
                "response_format": "markdown",
                "response_markdown": None,
                "response_json": None,
                "http_status": None,
                "error_code": None,
                "error_message": None,
                "upstream_latency_ms": None,
                "created_at": now_iso,
                "updated_at": now_iso,
                "completed_at": None,
            }
            tool_calls.append(call_row)
            _save("tool_calls.json", tool_calls)
            call_row["status"] = "running"
            call_row["updated_at"] = _now_iso()
            _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                             error_message=f"{k} must be an array of strings.",
                             cache_mode="bypass", response_format="markdown",
                             upstream_latency_ms=int((time.time() - t0) * 1000))
            _save("tool_calls.json", tool_calls)
            return _err("VALIDATION_ERROR", f"{k} must be an array of strings.")

    # Canonicalize query for caching/hash
    canon = _canonicalize_trial_query(req)
    if canon is None:
        canon = {}
    req_hash = _hash_req(canon)

    call_row = {
        "id": _ulid_like(),
        "client_id": client.get("id"),
        "tool_name": "trial_searcher",
        "status": "received",
        "request_json": req,
        "request_canonical_json": canon,
        "request_hash": req_hash,
        "source_system": "clinicaltrials",
        "cache_mode": "miss",
        "cache_ttl_seconds": 7 * 24 * 3600,
        "response_format": "markdown",
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    tool_calls.append(call_row)
    _save("tool_calls.json", tool_calls)

    def _finalize(payload):
        _save("tool_calls.json", tool_calls)
        return payload

    if client.get("status") in ("suspended", "deleted"):
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "rate_limited", error_code="CLIENT_NOT_ACTIVE",
                         error_message="Client is not active.", cache_mode="bypass",
                         response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("RATE_LIMIT", "Client not active.", error_code="CLIENT_NOT_ACTIVE"))

    def _within_window(row, seconds):
        dt = _parse_iso(row.get("created_at"))
        if dt is None:
            return False
        return (datetime.datetime.utcnow() - dt).total_seconds() <= seconds

    minute_cap = client.get("quota_requests_per_minute")
    day_cap = client.get("quota_requests_per_day")
    minute_count = 0
    day_count = 0
    for r in tool_calls:
        if r.get("client_id") != client.get("id"):
            continue
        if r.get("status") not in ("succeeded", "failed", "cancelled"):
            continue
        if _within_window(r, 60):
            minute_count += 1
        if _within_window(r, 24 * 3600):
            day_count += 1
    if isinstance(minute_cap, int) and minute_count >= minute_cap or isinstance(day_cap, int) and day_count >= day_cap:
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "rate_limited", error_code="RATE_LIMIT_EXCEEDED",
                         error_message="Client rate limit exceeded.", cache_mode="bypass",
                         response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT_EXCEEDED"))

    call_row["status"] = "running"
    call_row["updated_at"] = _now_iso()

    # Offline search against cached clinical_trials
    clinical_trials = _load("clinical_trials.json")

    # Parse optional date bounds (best effort)
    sdf = _parse_iso(start_date_from)
    sdt = _parse_iso(start_date_to)
    cdf = _parse_iso(completion_date_from)
    cdt = _parse_iso(completion_date_to)

    def _contains_any(hay, needles):
        if not needles:
            return True
        if not hay:
            return False
        h = str(hay).lower()
        return any(n.lower() in h for n in needles if isinstance(n, str) and n.strip())

    def _list_contains_any(lst, needles):
        if not needles:
            return True
        if not isinstance(lst, list) or not lst:
            return False
        lclst = [str(x).lower() for x in lst if x is not None]
        for n in needles:
            nn = str(n).lower()
            if any(nn in v for v in lclst):
                return True
        return False

    matches = []
    for tr in clinical_trials:
        if tr.get("status") == "tombstoned":
            continue
        # conditions
        if not _list_contains_any(tr.get("conditions"), req["conditions"]):
            continue
        # interventions
        if not _list_contains_any(tr.get("interventions"), req["interventions"]):
            continue
        # phase
        if req["phase"]:
            if not _list_contains_any(tr.get("phases"), req["phase"]):
                continue
        # recruiting_status vs overall_status
        if req["recruiting_status"]:
            if not _contains_any(tr.get("overall_status") or "", req["recruiting_status"]):
                continue
        # terms match against titles/sponsor/summary
        if req["terms"]:
            blob = " ".join([
                str(tr.get("brief_title") or ""),
                str(tr.get("official_title") or ""),
                str(tr.get("sponsor") or ""),
                str(tr.get("brief_summary") or "")
            ]).lower()
            ok = True
            for term in req["terms"]:
                tt = term.lower().strip()
                if tt and tt not in blob:
                    ok = False
                    break
            if not ok:
                continue

        # Date bounds cannot be accurately matched without structured trial dates; use fetched_at as proxy if present
        fetched = _parse_iso(tr.get("fetched_at"))
        if sdf and fetched and fetched < sdf:
            continue
        if sdt and fetched and fetched > sdt:
            continue
        if cdf and fetched and fetched < cdf:
            continue
        if cdt and fetched and fetched > cdt:
            continue

        matches.append(tr)

    # Sort by fetched_at desc
    def _sort_key(tr):
        dt = _parse_iso(tr.get("fetched_at")) or _parse_iso(tr.get("updated_at")) or datetime.datetime(1970, 1, 1)
        return dt

    matches.sort(key=_sort_key, reverse=True)

    # Page size (service default)
    page_size = 10
    page = matches[:page_size]

    md = []
    md.append("# Trial search results (cached)")
    q_parts = []
    if req["conditions"]:
        q_parts.append("conditions=" + ", ".join(req["conditions"]))
    if req["interventions"]:
        q_parts.append("interventions=" + ", ".join(req["interventions"]))
    if req["terms"]:
        q_parts.append("terms=" + ", ".join(req["terms"]))
    if req["recruiting_status"]:
        q_parts.append("status=" + ", ".join(req["recruiting_status"]))
    if req["phase"]:
        q_parts.append("phase=" + ", ".join(req["phase"]))
    if q_parts:
        md.append("**Query:** " + " | ".join(q_parts))
    md.append(f"**Returned:** {len(page)} of {len(matches)} cached trials")
    md.append("")

    if not page:
        md.append("_No cached trials matched this query._")
        markdown = "\n".join(md)
        call_row["cache_mode"] = "hit"  # cache read, even if empty
        client["last_seen_at"] = _now_iso()
        client["updated_at"] = _now_iso()
        for i, c in enumerate(api_clients):
            if c.get("id") == client.get("id"):
                api_clients[i] = client
                break
        _save("api_clients.json", api_clients)
        _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, cache_mode="hit",
                         cache_ttl_seconds=7 * 24 * 3600, response_format="markdown",
                         response_markdown=markdown, response_json={"total": len(matches), "returned": len(page)},
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(markdown)

    for i, tr in enumerate(page, 1):
        nct = tr.get("nct_id") or (tr.get("id")[4:] if isinstance(tr.get("id"), str) and tr.get("id").startswith("nct:") else None) or "NCT_UNKNOWN"
        title = tr.get("brief_title") or tr.get("official_title") or "Title unavailable"
        status = tr.get("overall_status") or "Status unavailable"
        md.append(f"{i}. **{nct}** — {title}")
        md.append(f"   - Status: {status}")
        if tr.get("source_url"):
            md.append(f"   - URL: {tr.get('source_url')}")
    markdown = "\n".join(md)

    call_row["cache_mode"] = "hit"

    client["last_seen_at"] = _now_iso()
    client["updated_at"] = _now_iso()
    for i, c in enumerate(api_clients):
        if c.get("id") == client.get("id"):
            api_clients[i] = client
            break
    _save("api_clients.json", api_clients)

    _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, cache_mode="hit",
                     cache_ttl_seconds=7 * 24 * 3600, response_format="markdown",
                     response_markdown=markdown, response_json={"total": len(matches), "returned": len(page)},
                     upstream_latency_ms=int((time.time() - t0) * 1000))
    return _finalize(markdown)

def variant_searcher(gene=None, hgvsp=None, hgvsc=None, rsid=None, region=None, significance=None, frequency_min=None, frequency_max=None, prediction_score_min=None, prediction_score_max=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, (int, float)):
            return datetime.datetime.utcfromtimestamp(dt)
        if not isinstance(dt, str):
            return None
        s = dt.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s2 = s[:-1]
        else:
            s2 = s
        try:
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _ulid_like():
        t_ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"ulid_{t_ms:x}_{rnd:x}"

    def _canonicalize_variant_query(q):
        def norm_str(s):
            return " ".join(s.strip().lower().split())

        cq = {}
        for k in ("gene", "hgvsp", "hgvsc", "rsid", "region", "significance"):
            v = q.get(k)
            if v is None:
                cq[k] = None
            else:
                if not isinstance(v, str):
                    return None
                vv = v.strip()
                cq[k] = norm_str(vv) if vv else None

        # ranges
        for rk in ("frequency_min", "frequency_max", "prediction_score_min", "prediction_score_max"):
            v = q.get(rk)
            if v is None:
                cq[rk] = None
            else:
                if not isinstance(v, (int, float)):
                    return None
                cq[rk] = float(v)

        return {k: cq[k] for k in sorted(cq.keys())}

    def _hash_req(canon_obj):
        s = json.dumps(canon_obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log_call_finish(tool_calls, call_row, status, http_status=None, error_code=None, error_message=None,
                         cache_mode=None, cache_ttl_seconds=None, response_format=None,
                         response_markdown=None, response_json=None, upstream_latency_ms=None):
        now = _now_iso()
        call_row["status"] = status
        call_row["updated_at"] = now
        call_row["completed_at"] = now
        call_row["http_status"] = http_status
        call_row["error_code"] = error_code
        call_row["error_message"] = error_message
        if cache_mode is not None:
            call_row["cache_mode"] = cache_mode
        if cache_ttl_seconds is not None:
            call_row["cache_ttl_seconds"] = cache_ttl_seconds
        if response_format is not None:
            call_row["response_format"] = response_format
        call_row["response_markdown"] = response_markdown
        call_row["response_json"] = response_json
        call_row["upstream_latency_ms"] = upstream_latency_ms
        return call_row

    t0 = time.time()
    now_iso = _now_iso()

    api_clients = _load("api_clients.json")
    client = None
    for c in api_clients:
        if c.get("status") == "active":
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active API client available to serve request.")

    tool_calls = _load("tool_calls.json")

    request_json = {
        "gene": gene,
        "hgvsp": hgvsp,
        "hgvsc": hgvsc,
        "rsid": rsid,
        "region": region,
        "significance": significance,
        "frequency_min": frequency_min,
        "frequency_max": frequency_max,
        "prediction_score_min": prediction_score_min,
        "prediction_score_max": prediction_score_max,
    }

    canon = _canonicalize_variant_query(request_json)
    if canon is None:
        canon = {}
    req_hash = _hash_req(canon)

    call_row = {
        "id": _ulid_like(),
        "client_id": client.get("id"),
        "tool_name": "variant_searcher",
        "status": "received",
        "request_json": request_json,
        "request_canonical_json": canon,
        "request_hash": req_hash,
        "source_system": "myvariant",
        "cache_mode": "miss",
        "cache_ttl_seconds": 3 * 24 * 3600,
        "response_format": "markdown",
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    tool_calls.append(call_row)
    _save("tool_calls.json", tool_calls)

    def _finalize(payload):
        _save("tool_calls.json", tool_calls)
        return payload

    if client.get("status") in ("suspended", "deleted"):
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "rate_limited", error_code="CLIENT_NOT_ACTIVE",
                         error_message="Client is not active.", cache_mode="bypass",
                         response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("RATE_LIMIT", "Client not active.", error_code="CLIENT_NOT_ACTIVE"))

    def _within_window(row, seconds):
        dt = _parse_iso(row.get("created_at"))
        if dt is None:
            return False
        return (datetime.datetime.utcnow() - dt).total_seconds() <= seconds

    minute_cap = client.get("quota_requests_per_minute")
    day_cap = client.get("quota_requests_per_day")
    minute_count = 0
    day_count = 0
    for r in tool_calls:
        if r.get("client_id") != client.get("id"):
            continue
        if r.get("status") not in ("succeeded", "failed", "cancelled"):
            continue
        if _within_window(r, 60):
            minute_count += 1
        if _within_window(r, 24 * 3600):
            day_count += 1
    if isinstance(minute_cap, int) and minute_count >= minute_cap or isinstance(day_cap, int) and day_count >= day_cap:
        call_row["status"] = "running"
        call_row["updated_at"] = _now_iso()
        _log_call_finish(tool_calls, call_row, "rate_limited", error_code="RATE_LIMIT_EXCEEDED",
                         error_message="Client rate limit exceeded.", cache_mode="bypass",
                         response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT_EXCEEDED"))

    call_row["status"] = "running"
    call_row["updated_at"] = _now_iso()

    # Validate rsid pattern if provided
    if rsid is not None:
        if not isinstance(rsid, str) or re.match(r"^rs[0-9]+$", rsid.strip()) is None:
            _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                             error_message="rsid must match ^rs[0-9]+$",
                             cache_mode="bypass", response_format="markdown",
                             upstream_latency_ms=int((time.time() - t0) * 1000))
            return _finalize(_err("VALIDATION_ERROR", "Invalid rsid format."))

    # Validate numeric ranges
    def _num(v):
        return isinstance(v, (int, float))

    if frequency_min is not None and (not _num(frequency_min) or frequency_min < 0 or frequency_min > 1):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="frequency_min must be a number in [0,1].",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "frequency_min must be in [0,1]."))
    if frequency_max is not None and (not _num(frequency_max) or frequency_max < 0 or frequency_max > 1):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="frequency_max must be a number in [0,1].",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "frequency_max must be in [0,1]."))
    if frequency_min is not None and frequency_max is not None and float(frequency_min) > float(frequency_max):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="frequency_min must be <= frequency_max.",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "frequency_min must be <= frequency_max."))

    if prediction_score_min is not None and not _num(prediction_score_min):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="prediction_score_min must be a number.",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "prediction_score_min must be a number."))
    if prediction_score_max is not None and not _num(prediction_score_max):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="prediction_score_max must be a number.",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "prediction_score_max must be a number."))
    if prediction_score_min is not None and prediction_score_max is not None and float(prediction_score_min) > float(prediction_score_max):
        _log_call_finish(tool_calls, call_row, "failed", error_code="INVALID_INPUT",
                         error_message="prediction_score_min must be <= prediction_score_max.",
                         cache_mode="bypass", response_format="markdown",
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(_err("VALIDATION_ERROR", "prediction_score_min must be <= prediction_score_max."))

    # Offline search against cached genetic_variants
    genetic_variants = _load("genetic_variants.json")

    def _match_str(field_val, qv):
        if qv is None:
            return True
        if field_val is None:
            return False
        return str(qv).lower() in str(field_val).lower()

    def _match_list(field_lst, qv):
        if qv is None:
            return True
        if not isinstance(field_lst, list) or not field_lst:
            return False
        q = str(qv).lower()
        return any(q in str(x).lower() for x in field_lst if x is not None)

    def _freq_in_range(freqs, fmin, fmax):
        if fmin is None and fmax is None:
            return True
        if not isinstance(freqs, dict):
            return False
        # Take min observed across any numeric entries in the dict as a best-effort
        vals = []
        def collect(x):
            if isinstance(x, dict):
                for v in x.values():
                    collect(v)
            elif isinstance(x, list):
                for v in x:
                    collect(v)
            elif isinstance(x, (int, float)):
                vals.append(float(x))
        collect(freqs)
        if not vals:
            return False
        v = min(vals)
        if fmin is not None and v < float(fmin):
            return False
        if fmax is not None and v > float(fmax):
            return False
        return True

    def _score_in_range(scores, smin, smax):
        if smin is None and smax is None:
            return True
        if not isinstance(scores, dict):
            return False
        vals = []
        def collect(x):
            if isinstance(x, dict):
                for v in x.values():
                    collect(v)
            elif isinstance(x, list):
                for v in x:
                    collect(v)
            elif isinstance(x, (int, float)):
                vals.append(float(x))
        collect(scores)
        if not vals:
            return False
        v = max(vals)
        if smin is not None and v < float(smin):
            return False
        if smax is not None and v > float(smax):
            return False
        return True

    matches = []
    for vr in genetic_variants:
        if vr.get("status") == "tombstoned":
            continue
        if not _match_str(vr.get("gene_symbol"), gene):
            continue
        if not _match_list(vr.get("hgvs_p"), hgvsp):
            continue
        if not _match_list(vr.get("hgvs_c"), hgvsc):
            continue
        if not _match_str(vr.get("rsid"), rsid):
            continue
        if significance is not None and not _match_str(vr.get("clinical_significance"), significance):
            continue
        if not _freq_in_range(vr.get("frequencies_json"), frequency_min, frequency_max):
            continue
        if not _score_in_range(vr.get("prediction_scores_json"), prediction_score_min, prediction_score_max):
            continue
        # region filter not supported offline (no index); do best-effort text match against raw_record_json/variant_id
        if region is not None:
            blob = (vr.get("variant_id") or "") + " " + json.dumps(vr.get("raw_record_json") or {}, ensure_ascii=False)
            if str(region).lower().strip() not in blob.lower():
                continue
        matches.append(vr)

    # Sort by fetched_at desc
    def _sort_key(vr):
        dt = _parse_iso(vr.get("fetched_at")) or _parse_iso(vr.get("updated_at")) or datetime.datetime(1970, 1, 1)
        return dt

    matches.sort(key=_sort_key, reverse=True)

    page_size = 10
    page = matches[:page_size]

    md = []
    md.append("# Variant search results (cached)")
    q = []
    if gene:
        q.append(f"gene={gene}")
    if hgvsp:
        q.append(f"hgvsp={hgvsp}")
    if hgvsc:
        q.append(f"hgvsc={hgvsc}")
    if rsid:
        q.append(f"rsid={rsid}")
    if region:
        q.append(f"region={region}")
    if significance:
        q.append(f"significance={significance}")
    if frequency_min is not None or frequency_max is not None:
        q.append(f"freq=[{frequency_min if frequency_min is not None else ''},{frequency_max if frequency_max is not None else ''}]")
    if prediction_score_min is not None or prediction_score_max is not None:
        q.append(f"score=[{prediction_score_min if prediction_score_min is not None else ''},{prediction_score_max if prediction_score_max is not None else ''}]")
    if q:
        md.append("**Query:** " + " | ".join(q))
    md.append(f"**Returned:** {len(page)} of {len(matches)} cached variants")
    md.append("")

    if not page:
        md.append("_No cached variants matched this query._")
        markdown = "\n".join(md)
        call_row["cache_mode"] = "hit"
        client["last_seen_at"] = _now_iso()
        client["updated_at"] = _now_iso()
        for i, c in enumerate(api_clients):
            if c.get("id") == client.get("id"):
                api_clients[i] = client
                break
        _save("api_clients.json", api_clients)
        _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, cache_mode="hit",
                         cache_ttl_seconds=3 * 24 * 3600, response_format="markdown",
                         response_markdown=markdown, response_json={"total": len(matches), "returned": len(page)},
                         upstream_latency_ms=int((time.time() - t0) * 1000))
        return _finalize(markdown)

    for i, vr in enumerate(page, 1):
        vid = vr.get("variant_id") or vr.get("id") or "VARIANT_UNKNOWN"
        g = vr.get("gene_symbol") or "Gene unavailable"
        rs = vr.get("rsid")
        sig = vr.get("clinical_significance")
        loc = None
        if vr.get("chromosome") and vr.get("position"):
            loc = f"{vr.get('chromosome')}:{vr.get('position')}"
        md.append(f"{i}. **{vid}**")
        md.append(f"   - Gene: {g}")
        if rs:
            md.append(f"   - rsID: {rs}")
        if loc:
            md.append(f"   - Location: {loc}")
        if sig:
            md.append(f"   - Clinical significance: {sig}")
        if vr.get("source_url"):
            md.append(f"   - URL: {vr.get('source_url')}")
    markdown = "\n".join(md)

    call_row["cache_mode"] = "hit"
    client["last_seen_at"] = _now_iso()
    client["updated_at"] = _now_iso()
    for i, c in enumerate(api_clients):
        if c.get("id") == client.get("id"):
            api_clients[i] = client
            break
    _save("api_clients.json", api_clients)

    _log_call_finish(tool_calls, call_row, "succeeded", http_status=200, cache_mode="hit",
                     cache_ttl_seconds=3 * 24 * 3600, response_format="markdown",
                     response_markdown=markdown, response_json={"total": len(matches), "returned": len(page)},
                     upstream_latency_ms=int((time.time() - t0) * 1000))
    return _finalize(markdown)

def whoami(api_key, **_extra):
    import json, os, datetime, hashlib, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "whoami"
    SOURCE_SYSTEM = "internal"
    RESPONSE_FORMAT = "json"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid(prefix):
        # Stable enough for local datastore: time (ms) + 80-bit randomness, hex, prefixed.
        ms = int(time.time() * 1000)
        rnd = secrets.token_hex(10)  # 80 bits
        return f"{prefix}{ms:013d}{rnd}"[:26]

    def _canonical_json(obj):
        # canonical json: sorted keys, compact separators, stable ordering
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _hash_request(canon_str):
        return hashlib.sha256(canon_str.encode("utf-8")).hexdigest()

    def _make_call_row(client_id, request_json):
        now = _now_iso()
        canon = _canonical_json(request_json)
        return {
            "id": _ulid("biomcp_call_"),
            "client_id": client_id,
            "tool_name": TOOL,
            "status": "received",
            "request_json": request_json,
            "request_canonical_json": json.loads(canon) if canon else {},
            "request_hash": _hash_request(canon),
            "source_system": SOURCE_SYSTEM,
            "cache_mode": "bypass",
            "cache_ttl_seconds": None,
            "response_format": RESPONSE_FORMAT,
            "response_markdown": None,
            "response_json": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "upstream_latency_ms": None,
            "created_at": now,
            "updated_at": now,
            "completed_at": None,
        }

    def _append_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _patch_call(tool_calls, call_id, **patch):
        now = _now_iso()
        for r in tool_calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                r.update(patch)
                r["updated_at"] = now
                if r.get("status") in ("succeeded", "failed", "rate_limited", "cancelled"):
                    r["completed_at"] = r.get("completed_at") or now
                _save("tool_calls.json", tool_calls)
                return r
        return None

    def _count_usage(tool_calls, client_id, now_dt):
        win60 = now_dt - datetime.timedelta(seconds=60)
        win24 = now_dt - datetime.timedelta(hours=24)
        c60 = 0
        c24 = 0
        for r in tool_calls:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            st = r.get("status")
            if st not in ("succeeded", "failed", "cancelled"):
                continue
            t = _parse_dt(r.get("created_at"))
            if not t:
                continue
            if t >= win60:
                c60 += 1
            if t >= win24:
                c24 += 1
        return c60, c24

    # Validate input
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    t0 = time.time()

    api_clients = _load("api_clients.json")
    tool_calls = _load("tool_calls.json")

    # Authenticate: match by client-visible value (stored hash string) OR by id.
    client = None
    for r in api_clients:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_hash") == api_key or r.get("id") == api_key:
            client = r
            break
    if not client:
        # No client_id available to log call; refuse UNAUTHORIZED.
        return _err("UNAUTHORIZED", "Missing/invalid API key")

    # Must log every invocation: create received before execution.
    call = _make_call_row(client.get("id"), {"api_key_present": True})
    _append_call(tool_calls, call)

    # Transition to running
    _patch_call(tool_calls, call["id"], status="running")

    # Client not active -> reject and record as rate_limited with CLIENT_NOT_ACTIVE
    if client.get("status") in ("suspended", "deleted"):
        _patch_call(
            tool_calls,
            call["id"],
            status="rate_limited",
            error_code="CLIENT_NOT_ACTIVE",
            error_message="Client is not active (suspended or deleted).",
            upstream_latency_ms=0,
        )
        return _err("UNAUTHORIZED", "Client not active", error_code="CLIENT_NOT_ACTIVE", client_id=client.get("id"))

    # Enforce rate limits (rolling)
    now_dt = _now_dt()
    used_60, used_24 = _count_usage(tool_calls, client.get("id"), now_dt)
    qpm = client.get("quota_requests_per_minute")
    qpd = client.get("quota_requests_per_day")

    # Validate quotas in store defensively
    if not isinstance(qpm, int) or not isinstance(qpd, int):
        _patch_call(
            tool_calls,
            call["id"],
            status="failed",
            error_code="INVALID_CLIENT_QUOTA",
            error_message="Client quota configuration invalid.",
            upstream_latency_ms=0,
        )
        return _err("CONFLICT", "Client quota configuration invalid", client_id=client.get("id"))

    if used_60 >= qpm or used_24 >= qpd:
        _patch_call(
            tool_calls,
            call["id"],
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests for this client in the rolling window.",
            upstream_latency_ms=0,
        )
        return _err(
            "RATE_LIMIT",
            "Rate limit exceeded",
            client_id=client.get("id"),
            quota_requests_per_minute=qpm,
            quota_requests_per_day=qpd,
            used_last_60s=used_60,
            used_last_24h=used_24,
        )

    # Success payload
    resp = {
        "api_client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
            "last_seen_at": _now_iso(),
            "quota_requests_per_minute": qpm,
            "quota_requests_per_day": qpd,
        },
        "scopes": ["tools:read", "tools:write"],
        "rate_limit": {
            "rolling_window_seconds": 60,
            "used": used_60,
            "limit": qpm,
            "remaining": max(0, qpm - used_60),
        },
        "quota": {
            "rolling_window_seconds": 86400,
            "used": used_24,
            "limit": qpd,
            "remaining": max(0, qpd - used_24),
        },
    }

    # Persist last_seen_at
    now_iso = _now_iso()
    updated = False
    for r in api_clients:
        if isinstance(r, dict) and r.get("id") == client.get("id"):
            r["last_seen_at"] = now_iso
            r["updated_at"] = now_iso
            updated = True
            break
    if updated:
        _save("api_clients.json", api_clients)

    latency_ms = int((time.time() - t0) * 1000)
    _patch_call(
        tool_calls,
        call["id"],
        status="succeeded",
        response_json=resp,
        upstream_latency_ms=latency_ms,
    )
    return resp

def tool_calls_lister(api_key, status=None, tool_name=None, source_system=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, random, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "tool_calls_lister"
    SOURCE_SYSTEM_INTERNAL = "internal"
    RESPONSE_FORMAT = "json"
    TTL_SECONDS = 60

    VALID_STATUS = ("received", "running", "succeeded", "failed", "rate_limited", "cancelled")
    VALID_TOOL = ("article_searcher", "article_details", "trial_searcher", "trial_protocol", "trial_locations", "trial_outcomes", "trial_references", "variant_searcher", "variant_details")
    # tool_calls schema uses: pubmed, clinicaltrials, myvariant, internal
    VALID_SOURCE = ("pubmed", "clinicaltrials_gov", "clinicaltrials", "myvariant", "internal")

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ms:013d}{rnd:020x}"[:26]

    def _append_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _patch_call(tool_calls, call_id, **patch):
        now_iso = _now_iso()
        for r in tool_calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                r.update(patch)
                r["updated_at"] = now_iso
                if r.get("status") in ("succeeded", "failed", "rate_limited", "cancelled"):
                    r["completed_at"] = r.get("completed_at") or now_iso
                _save("tool_calls.json", tool_calls)
                return r
        return None

    def _count_usage(tool_calls, client_id, now_dt):
        win60 = now_dt - datetime.timedelta(seconds=60)
        win24 = now_dt - datetime.timedelta(hours=24)
        c60 = 0
        c24 = 0
        for r in tool_calls:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            st = r.get("status")
            if st not in ("succeeded", "failed", "cancelled"):
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if created >= win60:
                c60 += 1
            if created >= win24:
                c24 += 1
        return c60, c24

    def _decode_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        b = json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    api_key = api_key.strip()

    if status is not None and status not in VALID_STATUS:
        return _err("VALIDATION_ERROR", "status must be one of: " + ", ".join(VALID_STATUS))
    if tool_name is not None and tool_name not in VALID_TOOL:
        return _err("VALIDATION_ERROR", "tool_name must be one of: " + ", ".join(VALID_TOOL))
    if source_system is not None and source_system not in ("pubmed", "clinicaltrials_gov", "myvariant"):
        return _err("VALIDATION_ERROR", "source_system must be one of: pubmed, clinicaltrials_gov, myvariant")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if order is None:
        order = "created_at_desc"
    if order not in ("created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "order must be created_at_desc or created_at_asc")

    dt_gte = _parse_dt(created_at_gte) if created_at_gte is not None else None
    if created_at_gte is not None and dt_gte is None:
        return _err("VALIDATION_ERROR", "created_at_gte must be RFC3339 date-time")
    dt_lte = _parse_dt(created_at_lte) if created_at_lte is not None else None
    if created_at_lte is not None and dt_lte is None:
        return _err("VALIDATION_ERROR", "created_at_lte must be RFC3339 date-time")
    if dt_gte and dt_lte and dt_gte > dt_lte:
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte")

    # Authenticate against api_key_hash OR id
    clients = _load("api_clients.json")
    tool_calls = _load("tool_calls.json")
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == api_key or c.get("id") == api_key:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    client_id = client.get("id")
    now_dt = _now_dt()
    now_iso = _now_iso()

    # Log this listing call itself
    call_id = "biomcp_call_" + _ulid_like("")
    req_obj = {
        "status": status,
        "tool_name": tool_name,
        "source_system": source_system,
        "created_at_gte": created_at_gte,
        "created_at_lte": created_at_lte,
        "limit": limit,
        "cursor": cursor,
        "order": order,
    }
    row = {
        "id": call_id,
        "client_id": client_id,
        "tool_name": TOOL,
        "status": "received",
        "request_json": req_obj,
        "request_canonical_json": req_obj,
        "request_hash": hashlib.sha256(json.dumps(req_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "source_system": SOURCE_SYSTEM_INTERNAL,
        "cache_mode": "bypass",
        "cache_ttl_seconds": TTL_SECONDS,
        "response_format": RESPONSE_FORMAT,
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    _append_call(tool_calls, row)

    # Client active check (must be recorded as rate_limited)
    if client.get("status") in ("suspended", "deleted"):
        _patch_call(tool_calls, call_id, status="rate_limited", error_code="CLIENT_NOT_ACTIVE", error_message="Caller api_client is not active.")
        return _err("RATE_LIMIT", "Client is not active.", tool_call_id=call_id, error_code="CLIENT_NOT_ACTIVE")

    # Rate limits
    quota_min = client.get("quota_requests_per_minute")
    quota_day = client.get("quota_requests_per_day")
    if not isinstance(quota_min, int):
        quota_min = 60
    if not isinstance(quota_day, int):
        quota_day = 5000
    c60, c24 = _count_usage(tool_calls, client_id, now_dt)
    if c60 >= quota_min or c24 >= quota_day:
        _patch_call(
            tool_calls, call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 60s for this client." if c60 >= quota_min else "Too many requests in the last 24h for this client."
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", tool_call_id=call_id, error_code="RATE_LIMIT_EXCEEDED")

    _patch_call(tool_calls, call_id, status="running")

    # Apply filters to tool_calls owned by this client
    rows = []
    for r in tool_calls:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        # exclude the lister call itself? real systems may include; keep it included
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if source_system is not None:
            # map clinicaltrials_gov filter to stored "clinicaltrials"
            want = "clinicaltrials" if source_system == "clinicaltrials_gov" else source_system
            if r.get("source_system") != want:
                continue
        cdt = _parse_dt(r.get("created_at"))
        if dt_gte and (cdt is None or cdt < dt_gte):
            continue
        if dt_lte and (cdt is None or cdt > dt_lte):
            continue
        rows.append(r)

    reverse = (order == "created_at_desc")
    rows.sort(key=lambda x: _parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=reverse)

    # Pagination with cursor = {"created_at": "...", "id": "..."}
    cur = _decode_cursor(cursor)
    if cur and isinstance(cur, dict):
        c_created = _parse_dt(cur.get("created_at"))
        c_id = cur.get("id")
        if c_created and isinstance(c_id, str):
            filtered = []
            for r in rows:
                r_dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                if reverse:
                    if r_dt < c_created or (r_dt == c_created and str(r.get("id")) < c_id):
                        filtered.append(r)
                else:
                    if r_dt > c_created or (r_dt == c_created and str(r.get("id")) > c_id):
                        filtered.append(r)
            rows = filtered

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"created_at": last.get("created_at"), "id": last.get("id")})

    resp_rows = []
    for r in page:
        rr = dict(r)
        # list view: omit heavy payloads by default
        rr.pop("request_json", None)
        rr.pop("request_canonical_json", None)
        rr.pop("response_markdown", None)
        rr.pop("response_json", None)
        resp_rows.append(rr)

    resp = {"tool_call_id": call_id, "rows": resp_rows, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

    _patch_call(tool_calls, call_id, status="succeeded", response_json=resp)

    # Update last_seen_at
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            c["last_seen_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            _save("api_clients.json", clients)
            break

    return {"data": resp}

def tool_calls_getter(api_key, id, include_payloads=None, **_extra):
    import json, os, datetime, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    TOOL_NAME = "tool_calls_getter"
    SOURCE_SYSTEM = "internal"
    RESPONSE_FORMAT = "json"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_call_id():
        # ULID-like enough for this datastore; must be unique.
        ms = int(time.time() * 1000)
        rnd = secrets.token_hex(8)
        return f"biomcp_call_{ms:013d}{rnd}"[:40]

    def _canonicalize(obj):
        try:
            return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        except TypeError:
            return json.dumps(str(obj), sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _hash(canon_str):
        return hashlib.sha256(canon_str.encode("utf-8")).hexdigest()

    def _append_tool_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _update_tool_call(tool_calls, call_id, **updates):
        now = _now_iso()
        updated = False
        for r in tool_calls:
            if r.get("id") == call_id:
                r.update(updates)
                r["updated_at"] = now
                updated = True
                break
        if updated:
            _save("tool_calls.json", tool_calls)
        return updated

    # ---- validate inputs (relaxed to match parameter schema) ----
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "API key missing or invalid")
    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if include_payloads is None:
        include_payloads = False
    if not isinstance(include_payloads, bool):
        return _err("VALIDATION_ERROR", "include_payloads must be a boolean", field="include_payloads")

    started = time.time()

    api_clients = _load("api_clients.json")
    tool_calls = _load("tool_calls.json")

    # ---- authenticate (explicit credential parameter) ----
    # IMPORTANT: Do not compare against a hash of a plaintext; stored value is already hashed.
    client = None
    for c in api_clients:
        if c.get("api_key_hash") == api_key or c.get("id") == api_key:
            client = c
            break
    if client is None:
        # Must still record the invocation attempt in tool_calls (best-effort with no client_id).
        call_id = _new_call_id()
        now = _now_iso()
        req_obj = {"id": id, "include_payloads": include_payloads}
        canon = _canonicalize(req_obj)
        req_hash = _hash(canon)
        received_row = {
            "id": call_id,
            "client_id": "unknown",
            "tool_name": TOOL_NAME,
            "status": "received",
            "request_json": req_obj,
            "request_canonical_json": json.loads(canon),
            "request_hash": req_hash,
            "source_system": SOURCE_SYSTEM,
            "cache_mode": "bypass",
            "cache_ttl_seconds": None,
            "response_format": RESPONSE_FORMAT,
            "response_markdown": None,
            "response_json": None,
            "http_status": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "API key missing/invalid.",
            "upstream_latency_ms": None,
            "created_at": now,
            "updated_at": now,
            "completed_at": now,
        }
        _append_tool_call(tool_calls, received_row)
        return _err("UNAUTHORIZED", "API key missing or invalid")

    client_id = client.get("id")

    # ---- create tool_calls row: received ----
    call_id = _new_call_id()
    now = _now_iso()
    req_obj = {"id": id, "include_payloads": include_payloads}
    canon_str = _canonicalize(req_obj)
    req_hash = _hash(canon_str)
    received_row = {
        "id": call_id,
        "client_id": client_id,
        "tool_name": TOOL_NAME,
        "status": "received",
        "request_json": req_obj,
        "request_canonical_json": json.loads(canon_str),
        "request_hash": req_hash,
        "source_system": SOURCE_SYSTEM,
        "cache_mode": "bypass",
        "cache_ttl_seconds": None,
        "response_format": RESPONSE_FORMAT,
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now,
        "updated_at": now,
        "completed_at": None,
    }
    _append_tool_call(tool_calls, received_row)

    # ---- client status check: must reject suspended/deleted and record as rate_limited ----
    if client.get("status") in ("suspended", "deleted"):
        _update_tool_call(
            tool_calls,
            call_id,
            status="rate_limited",
            error_code="CLIENT_NOT_ACTIVE",
            error_message="Client is not active.",
            completed_at=_now_iso(),
        )
        return _err("UNAUTHORIZED", "CLIENT_NOT_ACTIVE", client_id=client_id)

    # ---- rate limit enforcement (rolling windows) ----
    # Count terminal calls in the last 60s and last 24h for this client, excluding rate_limited itself.
    now_dt = _now_dt()
    minute_window_start = now_dt - datetime.timedelta(seconds=60)
    day_window_start = now_dt - datetime.timedelta(hours=24)
    count_minute = 0
    count_day = 0
    for r in tool_calls:
        if r.get("client_id") != client_id:
            continue
        st = r.get("status")
        if st not in ("succeeded", "failed", "cancelled"):
            continue
        created = _parse_dt(r.get("created_at"))
        if not created:
            continue
        if created >= minute_window_start:
            count_minute += 1
        if created >= day_window_start:
            count_day += 1

    qpm = client.get("quota_requests_per_minute")
    qpd = client.get("quota_requests_per_day")
    if isinstance(qpm, int) and qpm > 0 and count_minute >= qpm:
        _update_tool_call(
            tool_calls,
            call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 60s for this client.",
            completed_at=_now_iso(),
        )
        return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=60, limit=qpm)
    if isinstance(qpd, int) and qpd > 0 and count_day >= qpd:
        _update_tool_call(
            tool_calls,
            call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 24h for this client.",
            completed_at=_now_iso(),
        )
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", window_seconds=86400, limit=qpd)

    # ---- transition to running ----
    _update_tool_call(tool_calls, call_id, status="running")

    # ---- fetch the requested tool_call record for this client ----
    owned = None
    for r in tool_calls:
        if r.get("id") == id and r.get("client_id") == client_id:
            owned = r
            break

    if owned is None:
        _update_tool_call(
            tool_calls,
            call_id,
            status="failed",
            error_code="NOT_FOUND",
            error_message="Tool call not found or not owned by caller.",
            completed_at=_now_iso(),
        )
        return _err("NOT_FOUND", "Tool call not found", tool_call_id=id)

    # ---- success response ----
    # Update client's last_seen_at on successful tool execution.
    now_iso2 = _now_iso()
    for c in api_clients:
        if c.get("id") == client_id:
            c["last_seen_at"] = now_iso2
            c["updated_at"] = now_iso2
            _save("api_clients.json", api_clients)
            break

    # Prepare response envelope
    resp = {
        "tool_call": {
            "id": owned.get("id"),
            "client_id": owned.get("client_id"),
            "tool_name": owned.get("tool_name"),
            "status": owned.get("status"),
            "source_system": owned.get("source_system"),
            "cache_mode": owned.get("cache_mode"),
            "cache_ttl_seconds": owned.get("cache_ttl_seconds"),
            "response_format": owned.get("response_format"),
            "http_status": owned.get("http_status"),
            "error_code": owned.get("error_code"),
            "error_message": owned.get("error_message"),
            "upstream_latency_ms": owned.get("upstream_latency_ms"),
            "created_at": owned.get("created_at"),
            "updated_at": owned.get("updated_at"),
            "completed_at": owned.get("completed_at"),
        }
    }
    if include_payloads:
        resp["tool_call"]["request_json"] = owned.get("request_json")
        resp["tool_call"]["response_json"] = owned.get("response_json")
        resp["tool_call"]["response_markdown"] = owned.get("response_markdown")

    # Mark this getter call itself as succeeded and store response_json (metadata about what was returned).
    latency_ms = int((time.time() - started) * 1000)
    _update_tool_call(
        tool_calls,
        call_id,
        status="succeeded",
        response_json={
            "returned_tool_call_id": owned.get("id"),
            "include_payloads": include_payloads,
            "latency_ms": latency_ms,
        },
        completed_at=_now_iso(),
    )

    return resp

def api_clients_updater(api_key, id, status=None, name=None, quota_requests_per_minute=None, quota_requests_per_day=None, notes=None, **_extra):
    import json, os, datetime, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0072000" if __import__("os").path.isdir("./environment_mix/0072000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "api_clients_updater"
    SOURCE_SYSTEM = "internal"
    RESPONSE_FORMAT = "json"
    TTL_SECONDS = 60

    ALLOWED_STATUS = ("active", "suspended", "deleted")
    TRANSITIONS = {"active": ("suspended", "deleted"), "suspended": ("active", "deleted"), "deleted": ()}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ms:013d}{rnd:020x}"[:26]

    def _append_call(tool_calls, row):
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _patch_call(tool_calls, call_id, **patch):
        now_iso = _now_iso()
        for r in tool_calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                r.update(patch)
                r["updated_at"] = now_iso
                if r.get("status") in ("succeeded", "failed", "rate_limited", "cancelled"):
                    r["completed_at"] = r.get("completed_at") or now_iso
                _save("tool_calls.json", tool_calls)
                return r
        return None

    def _count_usage(tool_calls, client_id, now_dt):
        win60 = now_dt - datetime.timedelta(seconds=60)
        win24 = now_dt - datetime.timedelta(hours=24)
        c60 = 0
        c24 = 0
        for r in tool_calls:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            st = r.get("status")
            if st not in ("succeeded", "failed", "cancelled"):
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if created >= win60:
                c60 += 1
            if created >= win24:
                c24 += 1
        return c60, c24

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    api_key = api_key.strip()
    id = id.strip()

    if status is not None and status not in ALLOWED_STATUS:
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted")
    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "name must be a string of length 1..200")
    if quota_requests_per_minute is not None:
        if not isinstance(quota_requests_per_minute, int) or quota_requests_per_minute < 1 or quota_requests_per_minute > 100000:
            return _err("VALIDATION_ERROR", "quota_requests_per_minute must be an integer between 1 and 100000")
    if quota_requests_per_day is not None:
        if not isinstance(quota_requests_per_day, int) or quota_requests_per_day < 1 or quota_requests_per_day > 10000000:
            return _err("VALIDATION_ERROR", "quota_requests_per_day must be an integer between 1 and 10000000")
    if notes is not None:
        if not isinstance(notes, str) or len(notes) > 5000:
            return _err("VALIDATION_ERROR", "notes must be a string up to 5000 characters")

    clients = _load("api_clients.json")
    tool_calls = _load("tool_calls.json")

    # Authenticate against api_key_hash OR id (client-visible)
    caller = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == api_key or c.get("id") == api_key:
            caller = c
            break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    caller_id = caller.get("id")
    now_dt = _now_dt()
    now_iso = _now_iso()

    # Log this updater call
    call_id = "biomcp_call_" + _ulid_like("")
    req_obj = {
        "id": id,
        "status": status,
        "name": name,
        "quota_requests_per_minute": quota_requests_per_minute,
        "quota_requests_per_day": quota_requests_per_day,
        "notes": notes,
    }
    row = {
        "id": call_id,
        "client_id": caller_id,
        "tool_name": TOOL,
        "status": "received",
        "request_json": req_obj,
        "request_canonical_json": req_obj,
        "request_hash": hashlib.sha256(json.dumps(req_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "source_system": SOURCE_SYSTEM,
        "cache_mode": "bypass",
        "cache_ttl_seconds": TTL_SECONDS,
        "response_format": RESPONSE_FORMAT,
        "response_markdown": None,
        "response_json": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "upstream_latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "completed_at": None,
    }
    _append_call(tool_calls, row)

    # Calls from suspended/deleted must be rejected and recorded as rate_limited CLIENT_NOT_ACTIVE
    if caller.get("status") in ("suspended", "deleted"):
        _patch_call(tool_calls, call_id, status="rate_limited", error_code="CLIENT_NOT_ACTIVE", error_message="Caller api_client is not active.")
        return _err("RATE_LIMIT", "Client is not active.", tool_call_id=call_id, error_code="CLIENT_NOT_ACTIVE")

    # Rate limits
    quota_min = caller.get("quota_requests_per_minute")
    quota_day = caller.get("quota_requests_per_day")
    if not isinstance(quota_min, int):
        quota_min = 60
    if not isinstance(quota_day, int):
        quota_day = 5000
    c60, c24 = _count_usage(tool_calls, caller_id, now_dt)
    if c60 >= quota_min or c24 >= quota_day:
        _patch_call(
            tool_calls, call_id,
            status="rate_limited",
            error_code="RATE_LIMIT_EXCEEDED",
            error_message="Too many requests in the last 60s for this client." if c60 >= quota_min else "Too many requests in the last 24h for this client."
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", tool_call_id=call_id, error_code="RATE_LIMIT_EXCEEDED")

    # Scopes: datastore has no scopes model; treat authenticated active callers as allowed (fix audit defect).
    _patch_call(tool_calls, call_id, status="running")

    # Find target client
    target = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == id:
            target = c
            break
    if target is None:
        _patch_call(tool_calls, call_id, status="failed", error_code="NOT_FOUND", error_message="api_client not found")
        return _err("NOT_FOUND", "api_client not found", tool_call_id=call_id)

    # Apply updates with constraints
    # unique(name)
    if name is not None:
        for c in clients:
            if isinstance(c, dict) and c.get("id") != target.get("id") and c.get("name") == name:
                _patch_call(tool_calls, call_id, status="failed", error_code="CONFLICT", error_message="name must be unique")
                return _err("CONFLICT", "name must be unique", tool_call_id=call_id)

    # Enforce lifecycle transitions
    if status is not None:
        cur = target.get("status")
        if cur not in TRANSITIONS:
            _patch_call(tool_calls, call_id, status="failed", error_code="INVALID_TRANSITION", error_message="Unknown current status")
            return _err("INVALID_TRANSITION", "Unknown current status for lifecycle", tool_call_id=call_id)
        if status != cur:
            if status not in TRANSITIONS[cur]:
                _patch_call(tool_calls, call_id, status="failed", error_code="INVALID_TRANSITION", error_message=f"Illegal transition {cur} -> {status}")
                return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}", tool_call_id=call_id)

    # Update quota ranges consistent with schema constraints when possible
    # schema: quota_requests_per_minute between 1 and 6000; quota_requests_per_day between 1 and 200000
    if quota_requests_per_minute is not None:
        if quota_requests_per_minute < 1 or quota_requests_per_minute > 6000:
            _patch_call(tool_calls, call_id, status="failed", error_code="VALIDATION_ERROR", error_message="quota_requests_per_minute must be between 1 and 6000 (schema constraint)")
            return _err("VALIDATION_ERROR", "quota_requests_per_minute must be between 1 and 6000 (schema constraint)", tool_call_id=call_id)
    if quota_requests_per_day is not None:
        if quota_requests_per_day < 1 or quota_requests_per_day > 200000:
            _patch_call(tool_calls, call_id, status="failed", error_code="VALIDATION_ERROR", error_message="quota_requests_per_day must be between 1 and 200000 (schema constraint)")
            return _err("VALIDATION_ERROR", "quota_requests_per_day must be between 1 and 200000 (schema constraint)", tool_call_id=call_id)

    # Perform patch
    if status is not None:
        target["status"] = status
    if name is not None:
        target["name"] = name
    if quota_requests_per_minute is not None:
        target["quota_requests_per_minute"] = quota_requests_per_minute
    if quota_requests_per_day is not None:
        target["quota_requests_per_day"] = quota_requests_per_day
    if notes is not None:
        target["notes"] = notes

    target["updated_at"] = _now_iso()

    # Persist clients
    _save("api_clients.json", clients)

    resp = {"tool_call_id": call_id, "api_client": dict(target)}
    _patch_call(tool_calls, call_id, status="succeeded", response_json=resp)

    # Update last_seen_at for caller
    for c in clients:
        if isinstance(c, dict) and c.get("id") == caller_id:
            c["last_seen_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            _save("api_clients.json", clients)
            break

    return {"data": resp}
